# Improve prose spacing while preserving exact report/source quotations and target syntax.
import re
def clean(s):
 return re.sub(r'\b(at|after|before|by|within|deadline|detection|delivery|queue|start|trigger|exactly|until|October|revision)(?=\d)',r'\1 ',s)
for f in findings:
 for k in ['question','recommendation']: f[k]=clean(f[k])
 for k in ['component_propositions','rules','reasoning','limits']: f[k]=[clean(t) for t in f[k]]
